function Find-SkillDir {
  param([string]$Root, [string]$Name)
  Get-ChildItem -Path $Root -Recurse -Directory -ErrorAction SilentlyContinue |
    Where-Object { $_.Name -eq $Name -and (Test-Path (Join-Path $_.FullName 'SKILL.md')) } |
    Select-Object -First 1 -ExpandProperty FullName
}

function Copy-SkillToTarget {
  param([string]$SourceDir, [string]$DestRoot, [string]$SkillName)
  $dest = Join-Path $DestRoot $SkillName
  if (Test-Path $dest) { Remove-Item -LiteralPath $dest -Recurse -Force }
  Copy-Item -LiteralPath $SourceDir -Destination $dest -Recurse -Force
}

$targets = @(
  @{ Name='Cursor'; Path = Join-Path $env:USERPROFILE '.cursor\skills' },
  @{ Name='Claude'; Path = Join-Path $env:USERPROFILE '.claude\skills' },
  @{ Name='Codex'; Path = Join-Path $env:USERPROFILE '.codex\skills' }
)

$results = @()
foreach ($skill in $toInstall) {
  $src = Find-SkillDir -Root $mpRoot -Name $skill
  if (-not $src) { $results += [PSCustomObject]@{Skill=$skill; Status='NOT FOUND IN REPO'}; continue }
  foreach ($t in $targets) {
    Copy-SkillToTarget -SourceDir $src -DestRoot $t.Path -SkillName $skill
    $ok = Test-Path (Join-Path $t.Path "$skill\SKILL.md")
    $results += [PSCustomObject]@{Skill=$skill; Target=$t.Name; Status= if($ok){'INSTALLED'}else{'FAILED'} }
  }
}
$results | Format-Table -AutoSize
Write-Host "Installed count: $(($results | Where-Object Status -eq 'INSTALLED').Count)"

